1	//! Owner-pinned, bounded read-only acquisition of a KNB1 recovery bundle.
2	//! Successful inspection authenticates retained history, not a current output
3	//! file, durable mutation, or writer activation. No standalone fallback exists.
4	use super::{private_file, same_existing_file, sqlite_paths, Connection, Path, PathBuf};
5	use crate::{
6	    evidence_recovery_commitment::Limits,
7	    evidence_recovery_member::{Input, Membership, Object, Row},
8	    evidence_recovery_observation::Context,
9	    evidence_recovery_replay::{self as replay, Checkpoint, Replay},
10	};
11	use atproto_dasl::Cid;
12	use rusqlite::types::ValueRef;
13	use std::{
14	    sync::{
15	        atomic::{AtomicBool, Ordering},
16	        Arc,
17	    },
18	    time::{Duration, Instant},
19	};
20	
21	const SCHEMA: &str = include_str!("bundle.sql");
22	const APPLICATION_ID: i64 = 0x4b4e4231;
23	const MAX_SAFE: i64 = 9007199254740991;
24	const MAX_OBJECT: usize = 4194304;
25	
26	type Result<T> = std::result::Result<T, Error>;
27	#[derive(Debug, thiserror::Error)]
28	pub enum Error {
29	    #[error(transparent)]
30	    Store(#[from] super::Error),
31	    #[error(transparent)]
32	    Sql(#[from] rusqlite::Error),
33	    #[error(transparent)]
34	    Io(#[from] std::io::Error),
35	    #[error("invalid recovery bundle: {0}")]
36	    Invalid(&'static str),
37	    #[error("recovery bundle acquisition budget exhausted: {0}")]
38	    Budget(&'static str),
39	    #[error("recovery bundle inspection cancelled")]
40	    Cancelled,
41	    #[error(transparent)]
42	    Replay(#[from] replay::Error),
43	}
44	/// Acquisition limits apply before Rust copies each field. Encoded bytes are
45	/// not RSS: per-row containers, one bounded SQLite row, caches and replay working
46	/// state add overhead bounded by item/cell/work limits. No universal size cap.
47	#[derive(Clone)]
48	pub struct Budget {
49	    pub items: u64,
50	    pub acquired_bytes: u64,
51	    /// Pre-open sum of the main file and existing SQLite sidecars, not a fence
52	    /// against later filesystem growth or an exact SQLite heap ceiling.
53	    pub source_bytes: u64,
54	    pub replay_items: u64,
55	    pub replay_scan_bytes: u64,
56	    /// Includes acquisition and replay; cannot preempt arbitrary filesystem I/O.
57	    pub duration: Duration,
58	    pub cancelled: Arc<AtomicBool>,
59	}
60	pub struct Inspection {
61	    source: PathBuf,
62	    replay: Replay,
63	    acquired_bytes: u64,
64	    items: u64,
65	}
66	impl Inspection {
67	    /// Routing information only; a path may change after this snapshot closes.
68	    pub fn source(&self) -> &Path {
69	        &self.source
70	    }
71	    pub fn replay(&self) -> &Replay {
72	        &self.replay
73	    }
74	    pub fn acquired_bytes(&self) -> u64 {
75	        self.acquired_bytes
76	    }
77	    pub fn items(&self) -> u64 {
78	        self.items
79	    }
80	}
81	struct Work {
82	    budget: Budget,
83	    deadline: Instant,
84	    items: u64,
85	    bytes: u64,
86	}
87	impl Work {
88	    fn check(&self) -> Result<()> {
89	        if self.budget.cancelled.load(Ordering::Relaxed) {
90	            return Err(Error::Cancelled);
91	        }
92	        if Instant::now() >= self.deadline {
93	            return Err(Error::Budget("duration"));
94	        }
95	        Ok(())
96	    }
97	    fn charge(&mut self, items: u64, bytes: usize) -> Result<()> {
98	        self.check()?;
99	        self.items = self
100	            .items
101	            .checked_add(items)
102	            .ok_or(Error::Budget("items"))?;
103	        self.bytes = self
104	            .bytes
105	            .checked_add(bytes as u64)
106	            .ok_or(Error::Budget("acquired bytes"))?;
107	        if self.items > self.budget.items {
108	            return Err(Error::Budget("items"));
109	        }
110	        if self.bytes > self.budget.acquired_bytes {
111	            return Err(Error::Budget("acquired bytes"));
112	        }
113	        Ok(())
114	    }
115	}
116	fn require(ok: bool, why: &'static str) -> Result<()> {
117	    if ok {
118	        Ok(())
119	    } else {
120	        Err(Error::Invalid(why))
121	    }
122	}
123	fn integer(row: &rusqlite::Row<'_>, col: usize, min: i64, max: i64) -> Result<u64> {
124	    match row.get_ref(col)? {
125	        ValueRef::Integer(n) if (min..=max).contains(&n) => Ok(n as u64),
126	        _ => Err(Error::Invalid("integer storage class or bounds")),
127	    }
128	}
129	// Projection triple is typeof(column), length(CAST(column AS BLOB)), bounded
130	// substr(column...). Check type and full byte length before copying the slice.
131	fn cell(
132	    row: &rusqlite::Row<'_>,
133	    col: usize,
134	    min: usize,
135	    max: usize,
136	    text: bool,
137	    work: &mut Work,
138	) -> Result<Vec<u8>> {
139	    require(
140	        row.get_ref(col)? == ValueRef::Text(if text { b"text" } else { b"blob" }),
141	        "cell storage class",
142	    )?;
143	    let len = integer(row, col + 1, min as i64, max as i64)? as usize;
144	    let bytes = match (text, row.get_ref(col + 2)?) {
145	        (true, ValueRef::Text(b)) | (false, ValueRef::Blob(b)) => b,
146	        _ => return Err(Error::Invalid("projected cell storage class")),
147	    };
148	    require(bytes.len() == len, "cell truncated")?;
149	    if text {
150	        require(bytes.is_ascii() && !bytes.contains(&0), "ASCII text")?;
151	    }
152	    work.charge(0, len)?;
153	    Ok(bytes.to_vec())
154	}
155	fn cid(row: &rusqlite::Row<'_>, col: usize, work: &mut Work) -> Result<Cid> {
156	    let b = cell(row, col, 59, 59, true, work)?;
157	    let text = std::str::from_utf8(&b).map_err(|_| Error::Invalid("CID text"))?;
158	    let value: Cid = text.parse().map_err(|_| Error::Invalid("CID"))?;
159	    require(value.to_string() == text, "canonical CID spelling")?;
160	    let raw = value.to_bytes();
161	    require(
162	        raw.len() == 36 && raw[..4] == [1, 0x55, 0x12, 0x20],
163	        "raw SHA256 CID",
164	    )?;
165	    Ok(value)
166	}
167	fn projection(name: &str, max: usize) -> String {
168	    format!("typeof({name}),length(CAST({name} AS BLOB)),substr({name},1,{max})")
169	}
170	fn schema(conn: &Connection, work: &mut Work) -> Result<()> {
171	    let app: i64 = conn.query_row("PRAGMA application_id", [], |r| r.get(0))?;
172	    let version: i64 = conn.query_row("PRAGMA user_version", [], |r| r.get(0))?;
173	    let encoding: String = conn.query_row("PRAGMA encoding", [], |r| r.get(0))?;
174	    require(app == APPLICATION_ID && version == 1, "bundle profile")?;
175	    require(encoding == "UTF-8", "bundle encoding")?;
176	    let expected = Connection::open_in_memory()?;
177	    expected.execute_batch(SCHEMA)?;
178	    let query="SELECT substr(type,1,32),length(CAST(type AS BLOB)),substr(name,1,256),length(CAST(name AS BLOB)),substr(tbl_name,1,256),length(CAST(tbl_name AS BLOB)),substr(sql,1,65536),length(CAST(sql AS BLOB)) FROM sqlite_schema ORDER BY type,name";
179	    let mut actual = conn.prepare(query)?;
180	    let mut wanted = expected.prepare(query)?;
181	    let mut a = actual.query([])?;
182	    let mut e = wanted.query([])?;
183	    loop {
184	        work.check()?;
185	        match (a.next()?, e.next()?) {
186	            (None, None) => return Ok(()),
187	            (Some(a), Some(e)) => {
188	                for c in 0..8 {
189	                    require(a.get_ref(c)? == e.get_ref(c)?, "bundle schema")?;
190	                }
191	            }
192	            _ => return Err(Error::Invalid("bundle schema")),
193	        }
194	    }
195	}
196	fn identity(conn: &Connection, context: &Context, work: &mut Work) -> Result<()> {
197	    let query = format!(
198	        "SELECT singleton,{},{},profile,{},{},{} FROM bundle_identity",
199	        projection("bundle", 32),
200	        projection("observer", 80),
201	        projection("archive", 32),
202	        projection("scope", 32),
203	        projection("issuer", 80)
204	    );
205	    let mut stmt = conn.prepare(&query)?;
206	    let mut rows = stmt.query([])?;
207	    let row = rows
208	        .next()?
209	        .ok_or(Error::Invalid("missing bundle identity"))?;
210	    work.charge(1, 16)?;
211	    require(integer(row, 0, 1, 1)? == 1, "identity singleton")?;
212	    require(
213	        cell(row, 1, 32, 32, false, work)? == context.bundle,
214	        "bundle pin",
215	    )?;
216	    require(
217	        cell(row, 4, 56, 80, true, work)? == context.observer.as_bytes(),
218	        "observer pin",
219	    )?;
220	    require(
221	        integer(row, 7, 2, 3)? == context.profile as u64,
222	        "profile pin",
223	    )?;
224	    require(
225	        cell(row, 8, 32, 32, false, work)? == context.archive,
226	        "archive pin",
227	    )?;
228	    require(
229	        cell(row, 11, 32, 32, false, work)? == context.scope,
230	        "scope pin",
231	    )?;
232	    require(
233	        cell(row, 14, 56, 80, true, work)? == context.issuer.as_bytes(),
234	        "issuer pin",
235	    )?;
236	    require(rows.next()?.is_none(), "identity cardinality")
237	}
238	struct EncodedRow {
239	    sequence: u64,
240	    manifest: Vec<u8>,
241	    receipt: Vec<u8>,
242	    proof: Vec<u8>,
243	}
244	fn objects(
245	    conn: &Connection,
246	    table: &str,
247	    min: usize,
248	    work: &mut Work,
249	) -> Result<Vec<(Cid, Vec<u8>)>> {
250	    let query = format!(
251	        "SELECT {},{} FROM {table} NOT INDEXED ORDER BY cid",
252	        projection("cid", 59),
253	        projection("bytes", MAX_OBJECT)
254	    );
255	    let mut stmt = conn.prepare(&query)?;
256	    let mut rows = stmt.query([])?;
257	    let mut out = Vec::new();
258	    while let Some(row) = rows.next()? {
259	        work.charge(1, 0)?;
260	        out.push((
261	            cid(row, 0, work)?,
262	            cell(row, 3, min, MAX_OBJECT, false, work)?,
263	        ));
264	    }
265	    Ok(out)
266	}
267	/// Inspect one pinned SQLite snapshot. The owner must retain checkpoints outside
268	/// the file. SQLite can initialize WAL/SHM coordination files; main records are
269	/// never rewritten. A hot journal refuses. No output path or writer is selected.
270	pub fn inspect(
271	    path: &Path,
272	    context: Context,
273	    checkpoint: Option<&Checkpoint>,
274	    budget: Budget,
275	) -> Result<Inspection> {
276	    inspect_snapshot(path, context, checkpoint, budget, || {})
277	}
278	fn inspect_snapshot(
279	    path: &Path,
280	    context: Context,
281	    checkpoint: Option<&Checkpoint>,
282	    budget: Budget,
283	    after_identity: impl FnOnce(),
284	) -> Result<Inspection> {
285	    require(
286	        !budget.duration.is_zero() && budget.duration <= Duration::from_secs(3600),
287	        "duration",
288	    )?;
289	    let deadline = Instant::now()
290	        .checked_add(budget.duration)
291	        .ok_or(Error::Budget("duration"))?;
292	    let mut work = Work {
293	        budget,
294	        deadline,
295	        items: 0,
296	        bytes: 0,
297	    };
298	    work.check()?;
299	    private_file(path)?;
300	    let source = std::fs::canonicalize(path)?;
301	    let mut existing: Vec<PathBuf> = Vec::new();
302	    let mut source_bytes = 0u64;
303	    for path in sqlite_paths(&source) {
304	        work.check()?;
305	        let metadata = match std::fs::symlink_metadata(&path) {
306	            Ok(meta) => meta,
307	            Err(e) if e.kind() == std::io::ErrorKind::NotFound && path != source => continue,
308	            Err(e) => return Err(e.into()),
309	        };
310	        private_file(&path)?;
311	        require(
312	            !existing.iter().any(|p| same_existing_file(p, &path)),
313	            "aliased SQLite source files",
314	        )?;
315	        source_bytes = source_bytes
316	            .checked_add(metadata.len())
317	            .ok_or(Error::Budget("source bytes"))?;
318	        if source_bytes > work.budget.source_bytes {
319	            return Err(Error::Budget("source bytes"));
320	        }
321	        existing.push(path);
322	    }
323	    // surface-write: evidence-bundle-source:database-wal,evidence-bundle-source:database-shm
324	    let conn = crate::persistence::open_sqlite_recovery_source(
325	        crate::persistence::SurfaceWrite::EvidenceBundleSource,
326	        &source,
327	    )?;
328	    conn.set_limit(
329	        rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
330	        5 * 1024 * 1024,
331	    )?;
332	    conn.busy_timeout(work.budget.duration.min(Duration::from_millis(250)))?;
333	    let cancel = work.budget.cancelled.clone();
334	    conn.progress_handler(
335	        1000,
336	        Some(move || cancel.load(Ordering::Relaxed) || Instant::now() >= deadline),
337	    )?;
338	    let result = (|| {
339	        conn.execute_batch("PRAGMA query_only=ON; PRAGMA trusted_schema=OFF; PRAGMA cache_size=-4096; PRAGMA mmap_size=0; BEGIN;")?;
340	        schema(&conn, &mut work)?;
341	        identity(&conn, &context, &mut work)?;
342	        after_identity();
343	        let mut plan = None;
344	        let query = format!(
345	            "SELECT singleton,{} FROM member_plan",
346	            projection("envelope", 4096)
347	        );
348	        let mut stmt = conn.prepare(&query)?;
349	        let mut rows = stmt.query([])?;
350	        while let Some(row) = rows.next()? {
351	            work.charge(1, 8)?;
352	            integer(row, 0, 1, 1)?;
353	            require(plan.is_none(), "plan cardinality")?;
354	            plan = Some(cell(row, 1, 1, 4096, false, &mut work)?);
355	        }
356	        let mut membership = Vec::new();
357	        let query = format!(
358	            "SELECT {},length FROM member_membership NOT INDEXED ORDER BY cid",
359	            projection("cid", 59)
360	        );
361	        let mut stmt = conn.prepare(&query)?;
362	        let mut rows = stmt.query([])?;
363	        while let Some(row) = rows.next()? {
364	            work.charge(1, 8)?;
365	            membership.push((
366	                cid(row, 0, &mut work)?,
367	                integer(row, 3, 1, MAX_OBJECT as i64)?,
368	            ));
369	        }
370	        let mut records = Vec::new();
371	        let query = format!(
372	            "SELECT sequence,{},{},{} FROM member_records NOT INDEXED ORDER BY sequence",
373	            projection("manifest", 65536),
374	            projection("receipt", 65536),
375	            projection("envelope", 16384)
376	        );
377	        let mut stmt = conn.prepare(&query)?;
378	        let mut rows = stmt.query([])?;
379	        while let Some(row) = rows.next()? {
380	            work.charge(1, 8)?;
381	            records.push(EncodedRow {
382	                sequence: integer(row, 0, 1, MAX_SAFE)?,
383	                manifest: cell(row, 1, 1, 65536, false, &mut work)?,
384	                receipt: cell(row, 4, 1, 65536, false, &mut work)?,
385	                proof: cell(row, 7, 1, 16384, false, &mut work)?,
386	            });
387	        }
388	        let original = objects(&conn, "member_objects", 0, &mut work)?;
389	        let candidates = objects(&conn, "restored_objects", 1, &mut work)?;
390	        let mut observations = Vec::new();
391	        let query = format!(
392	            "SELECT sequence,{} FROM observations NOT INDEXED ORDER BY sequence",
393	            projection("envelope", 16384)
394	        );
395	        let mut stmt = conn.prepare(&query)?;
396	        let mut rows = stmt.query([])?;
397	        while let Some(row) = rows.next()? {
398	            work.charge(1, 8)?;
399	            require(
400	                integer(row, 0, 1, MAX_SAFE)? == observations.len() as u64 + 1,
401	                "observation coordinate",
402	            )?;
403	            observations.push(cell(row, 1, 1, 16384, false, &mut work)?);
404	        }
405	        work.check()?;
406	        let membership: Vec<_> = membership
407	            .iter()
408	            .map(|(cid, length)| Membership {
409	                cid,
410	                length: *length,
411	            })
412	            .collect();
413	        let records: Vec<_> = records
414	            .iter()
415	            .map(|r| Row {
416	                sequence: r.sequence,
417	                manifest: &r.manifest,
418	                receipt: &r.receipt,
419	                proof: &r.proof,
420	            })
421	            .collect();
422	        let original: Vec<_> = original
423	            .iter()
424	            .map(|(cid, bytes)| Object { cid, bytes })
425	            .collect();
426	        let candidates: Vec<_> = candidates
427	            .iter()
428	            .map(|(cid, bytes)| Object { cid, bytes })
429	            .collect();
430	        let observations: Vec<_> = observations.iter().map(Vec::as_slice).collect();
431	        let input = Input {
432	            context: &context,
433	            plan: plan.as_deref(),
434	            membership: &membership,
435	            records: &records,
436	            objects: &original,
437	        };
438	        let limits = Limits {
439	            items: work.budget.replay_items,
440	            bytes: work.budget.replay_scan_bytes,
441	            duration: deadline.saturating_duration_since(Instant::now()),
442	            cancelled: work.budget.cancelled.clone(),
443	        };
444	        let replay = replay::verify(input, &candidates, &observations, checkpoint, limits)?;
445	        work.check()?;
446	        Ok(Inspection {
447	            source,
448	            replay,
449	            acquired_bytes: work.bytes,
450	            items: work.items,
451	        })
452	    })();
453	    // Normalize VM interruption after deadline/cancellation; do not conceal an
454	    // independent schema/data error when neither condition has occurred.
455	    work.check()?;
456	    result
457	}
458	
459	#[cfg(test)]
460	mod snapshot_tests {
461	    use super::*;
462	    fn fixture() -> (tempfile::TempDir, PathBuf, Context, Budget) {
463	        let dir = tempfile::tempdir().unwrap();
464	        let name = "profile2-restored-failure-observed";
