496	                .unwrap()
497	        };
498	        let context = Context {
499	            bundle: bytes("bundle"),
500	            profile: 2,
501	            archive: bytes("archive"),
502	            scope: bytes("scope"),
503	            issuer: c["issuer"].as_str().unwrap().into(),
504	            observer: c["observer"].as_str().unwrap().into(),
505	        };
506	        let budget = Budget {
507	            items: 10000,
508	            acquired_bytes: 32 * 1024 * 1024,
509	            source_bytes: 64 * 1024 * 1024,
510	            replay_items: 10000,
511	            replay_scan_bytes: 128 * 1024 * 1024,
512	            duration: Duration::from_secs(10),
513	            cancelled: Arc::new(AtomicBool::new(false)),
514	        };
515	        let path = dir.path().join(format!("{name}.sqlite"));
516	        (dir, path, context, budget)
517	    }
518	    #[test]
519	    fn later_wal_changes_cannot_mix_into_the_pinned_snapshot() {
520	        let (_dir, path, context, budget) = fixture();
521	        let writer = Connection::open(&path).unwrap();
522	        writer.execute_batch("PRAGMA journal_mode=WAL;").unwrap();
523	        let inspected = inspect_snapshot(&path, context.clone(), None, budget.clone(), || {
524	            writer
525	                .execute("INSERT INTO observations VALUES(8,?)", [vec![0u8]])
