1	#![cfg(feature = "v2-storage")]
2	use kan::{
3	    evidence_recovery_observation::Context,
4	    evidence_recovery_replay::Checkpoint,
5	    evidence_service::unhex,
6	    evidence_store::{
7	        self as store,
8	        bundle::{self, Budget, Error},
9	    },
10	};
11	use rusqlite::Connection;
12	use serde_json::Value;
13	use std::{
14	    path::{Path, PathBuf},
15	    process::Command,
16	    sync::{atomic::AtomicBool, Arc},
17	    time::{Duration, Instant},
18	};
19	fn budget() -> Budget {
20	    Budget {
21	        items: 10000,
22	        acquired_bytes: 32 * 1024 * 1024,
23	        source_bytes: 64 * 1024 * 1024,
24	        replay_items: 10000,
25	        replay_scan_bytes: 128 * 1024 * 1024,
26	        duration: Duration::from_secs(10),
27	        cancelled: Arc::new(AtomicBool::new(false)),
28	    }
29	}
30	fn cases() -> Vec<Value> {
31	    serde_json::from_str::<Value>(include_str!("../.design/fixtures/recovery-replay-v1.json"))
32	        .unwrap()["cases"]
33	        .as_array()
34	        .unwrap()
35	        .clone()
36	}
37	fn pins(v: &Value) -> Context {
38	    let c = &v["member"]["context"];
39	    let bytes = |s: &str| {
40	        unhex(c[s].as_str().unwrap(), 32)
41	            .unwrap()
42	            .try_into()
43	            .unwrap()
44	    };
45	    Context {
46	        bundle: bytes("bundle"),
47	        profile: c["profile"].as_u64().unwrap() as u8,
48	        archive: bytes("archive"),
49	        scope: bytes("scope"),
50	        issuer: c["issuer"].as_str().unwrap().into(),
51	        observer: c["observer"].as_str().unwrap().into(),
52	    }
53	}
54	fn checkpoint(v: &Value) -> Option<Checkpoint> {
55	    (!v["checkpoint"].is_null()).then(|| Checkpoint {
56	        context: pins(v),
57	        sequence: v["checkpoint"][0].as_u64().unwrap(),
58	        statement: v["checkpoint"][1].as_str().unwrap().parse().unwrap(),
59	    })
60	}
61	fn construct(dir: &Path, name: Option<&str>, encoding: &str) {
62	    let python = std::env::var_os("KAN_TLS_ORACLE_PYTHON").unwrap_or_else(|| "python3".into());
63	    let mut cmd = Command::new(python);
64	    cmd.arg(".design/tools/recovery_bundle_files.py")
65	        .arg(dir)
66	        .arg("--encoding")
67	        .arg(encoding);
68	    if let Some(name) = name {
69	        cmd.arg("--case").arg(name);
70	    }
71	    let output = cmd.output().unwrap();
72	    assert!(
73	        output.status.success(),
74	        "{}",
75	        String::from_utf8_lossy(&output.stderr)
76	    );
77	}
78	fn fixture() -> (tempfile::TempDir, PathBuf, Value) {
79	    let dir = tempfile::tempdir().unwrap();
80	    let name = "profile2-restored-failure-observed";
81	    construct(dir.path(), Some(name), "UTF-8");
82	    let path = dir.path().join(format!("{name}.sqlite"));
83	    let v = cases().into_iter().find(|v| v["name"] == name).unwrap();
