    let c = &v["member"]["context"];
    let bytes = |s: &str| unhex(c[s].as_str().unwrap(), 32).unwrap().try_into().unwrap();
    Context {
        bundle: bytes("bundle"),
        profile: c["profile"].as_u64().unwrap() as u8,
        archive: bytes("archive"),
        scope: bytes("scope"),
        issuer: c["issuer"].as_str().unwrap().into(),
